function isDecomposable(s) {
  let pairs = 0;
  let start = 0;
  for (let i = 1; i <= s.length; i++) {
    if (i < s.length && s[i] === s[start]) {
      continue;
    }
    const runLength = i - start;
    if (runLength % 3 === 1) {
      return false;
    }
    if (runLength % 3 === 2) {
      pairs++;
    }
    start = i;
  }
  return pairs === 1;
}

