function isDecomposable(s) {
  const same = (at, len) => at + len <= s.length && [...s.slice(at, at + len)].every(c => c === s[at]);
  const can = (at, usedPair) => {
    if (at === s.length) return usedPair;
    if (same(at, 3) && can(at + 3, usedPair)) return true;
    return !usedPair && same(at, 2) && can(at + 2, true);
  };
  return can(0, false);
}

