function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  if (size === 'small') {
    const digits = 1 + pick(3);
    const runs = 1 + pick(4);
    let s = '';
    for (let r = 0; r < runs; r++) {
      const len = rand() < 0.6 ? 3 * pick(3) + 2 * pick(2) || 3 : 1 + pick(7);
      s += String(pick(digits)).repeat(len);
    }
    return [s];
  }
  // Large: runs of different digits, all of length 3k except one of length 3k + 2, then maybe break it.
  const lengths = [];
  let total = 0;
  while (total < 960) {
    const len = 3 * (1 + pick(10));
    lengths.push(len);
    total += len;
  }
  lengths[pick(lengths.length)] += 2;
  const mode = pick(3);
  if (mode === 1) lengths[pick(lengths.length)] += 1;
  if (mode === 2) lengths[pick(lengths.length)] += 2;
  let s = '';
  let prev = -1;
  for (const len of lengths) {
    let d = pick(10);
    if (d === prev) d = (d + 1) % 10;
    s += String(d).repeat(len);
    prev = d;
  }
  return [s.slice(0, 1000)];
}
